ures}'=$verify_bffc6f31a0ed827b$[{"id":"preserved-personal-rule","kind":"other","name":"Reglas de la variante personal","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"","showInActions":false}]$verify_bffc6f31a0ed827b$::jsonb and payload#>'{rules,definition,description}'=$verify_62e4d54fea40cf3e$[{"id":"player-description","section":"description","type":"paragraph","provenance":"campaign","sourceIds":["ece-current-copy"],"text":"Brújula."}]$verify_62e4d54fea40cf3e$::jsonb and payload#>'{catalog,revision}'=$verify_6b86b273ff34fce1$1$verify_6b86b273ff34fce1$::jsonb and revision=2) union all select 'inventory:inv_a505d191e9350f17b3789543cb40152d' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_a505d191e9350f17b3789543cb40152d' and payload#>'{features}'=$verify_bffc6f31a0ed827b$[{"id":"preserved-personal-rule","kind":"other","name":"Reglas de la variante personal","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"","showInActions":false}]$verify_bffc6f31a0ed827b$::jsonb and payload#>'{rules,definition,description}'=$verify_428060327d18ba57$[{"id":"player-description","section":"description","type":"paragraph","provenance":"campaign","sourceIds":["ece-current-copy"],"text":"Cristales de reserva."}]$verify_428060327d18ba57$::jsonb and payload#>'{catalog,revision}'=$verify_6b86b273ff34fce1$1$verify_6b86b273ff34fce1$::jsonb and revision=2) union all select 'inventory:inv_aee96a5a7c9f10db7e215b35eee2ee93' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_aee96a5a7c9f10db7e215b35eee2ee93' and payload#>'{description}'=$verify_f6dd41d6d6cb54a8$"Objeto · Precio base · Peso\nHerramientas de herrero · 20 po · 8 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_f6dd41d6d6cb54a8$